int main(void) {
    long long N, M;
    if (scanf("%lld %lld", &N, &M) != 2) return 0;

    /* 
       Let a_i = number of times index i got +2
           b_i = number of times index i got +1
       Then x_i = 2a_i + b_i, with:
           sum a_i = M, sum b_i = M, and for every i, not both used in same operation pairing.

       Existence of a pairing between +2 multiset and +1 multiset with no self-pair
       is equivalent to max_i (a_i + b_i) <= M.

       So we count integer vectors x such that there exists integers a_i with:
           0 <= a_i <= floor(x_i/2),
           b_i = x_i - 2a_i >= 0,
           sum a_i = M,
           and a_i + b_i = x_i - a_i <= M  => a_i >= x_i - M.

       Thus for each i:
           max(0, x_i - M) <= a_i <= floor(x_i/2)
       and sum a_i = M.

       This is feasible iff sum floor(x_i/2) >= M.
       Since sum x_i = 3M, this is equivalent to number of odd x_i <= M.

       Therefore answer = number of N-tuples of nonnegative integers summing to 3M
       with at most M odd entries.

       If exactly k entries are odd, then k must have same parity as 3M, i.e. parity of M,
       and 0 <= k <= min(N, M).
       Write odd entries as 2y+1, even entries as 2y.
       Then total y-sum = (3M - k)/2.
       Count:
           C(N, k) * C((3M-k)/2 + N - 1, N - 1)
    */

    long long Kmax = (N < M ? N : M);
    long long maxT = (3 * M + N); /* enough for largest n in combinations */

    long long *fact = (long long*)malloc((maxT + 1) * sizeof(long long));
    long long *invfact = (long long*)malloc((maxT + 1) * sizeof(long long));
    if (!fact || !invfact) return 0;

    fact[0] = 1;
    for (long long i = 1; i <= maxT; ++i) fact[i] = fact[i - 1] * i % MOD;
    invfact[maxT] = mod_pow(fact[maxT], MOD - 2);
    for (long long i = maxT; i > 0; --i) invfact[i - 1] = invfact[i] * i % MOD;

    #define C(n,r) (((r) < 0 || (r) > (n)) ? 0LL : fact[n] * invfact[r] % MOD * invfact[(n)-(r)] % MOD)

    long long ans = 0;
    for (long long k = 0; k <= Kmax; ++k) {
        if ((k & 1LL) != (M & 1LL)) continue;
        long long s = (3 * M - k) / 2;
        long long ways_choose_odd = C(N, k);
        long long ways_values = C(s + N - 1, N - 1);
        ans = (ans + ways_choose_odd * ways_values) % MOD;
    }

    printf("%lld\n", ans);

    free(fact);
    free(invfact);
    return 0;
}

