    // Too large for direct DP if M is big
    // Need generating functions approach
    // Each element contributes x in [0,2M], with ceil(x/2) tracked
    // GF for one element: sum_{x=0}^{2M} z^x * w^{ceil(x/2)}
    // We need coefficient of z^{3M} * w^{<=2M} in (GF)^N
    // This might be feasible with polynomial multiplication
    // Actually let's use the substitution: let x = 2a+b, a>=0, b in {0,1}
    // ceil(x/2) = a + b, floor(x/2) = a
    // GF = sum_{a=0}^{M} sum_{b=0}^{1} z^{2a+b} * w^{a+b}
    //    = sum_{a=0}^{M} (zw)^a * z^{2a}/z^{...} hmm
    // Let me just do DP with states (elements placed, sum, sum_ceil) but that's O(N*M^2)
    // For small M this works
    long long limit = 2*M;
    // dp over N elements, sum in [0,3M], sum_ceil in [0, 2M+N] but capped
    // Actually sum_ceil <= sum (since ceil(x/2) <= x for x>=1, and =0 for x=0)
    // sum_ceil ranges 0..3M
    // dp[sum][sum_ceil]
    vector<vector<long long>> dp(3*M+1, vector<long long>(2*M+2, 0));
