    if not input_data:
        return
    N = int(input_data[0])
    M = int(input_data[1])

    max_n = M + N
    fact = [1] * (max_n + 1)
    for i in range(1, max_n + 1):
        fact[i] = fact[i-1] * i % MOD

    invfact = [1] * (max_n + 1)
    invfact[max_n] = modinv(fact[max_n])
    for i in range(max_n, 0, -1):
        invfact[i-1] = invfact[i] * i % MOD

    def comb(n, k):
        if k < 0 or k > n:
            return 0
        return fact[n] * invfact[k] % MOD * invfact[n-k] % MOD

    ways = comb(M + N - 1, N - 1)
    ans = ways * ways % MOD
    print(ans)

