        // Count sequences x[1..N], x[i]>=0, sum=3M
        // such that sum(floor(x[i]/2)) >= M and sum(max(0,x[i]-M)) <= M
        // Use inclusion-exclusion or DP
        // DP over positions, tracking (sum_x, sum_floor, sum_excess)
        // sum_x must be 3M, sum_floor >= M, sum_excess <= M
        // Let's do DP[pos][sx][sf][se] but dimensions too large
        // Actually sf = sum floor(x[i]/2), se = sum max(0,x[i]-M)
        // Note: floor(x/2) = (x - (x%2))/2, and max(0,x-M)
        // For x in [0,3M], these are bounded
        // sf in [0, 3M/2], se in [0, 3M-N*0] but capped
        // This might be feasible with small M
        // Let's just brute force for small inputs and see pattern
        // Actually let me think of a smarter approach
        // For the constraint sum(floor(x[i]/2)) >= M:
        // sum(floor(x[i]/2)) = (sum(x[i]) - #{i: x[i] odd}) / 2 = (3M - odd_count)/2
        // So (3M - odd_count)/2 >= M => 3M - odd_count >= 2M => M >= odd_count
        // So constraint 1: number of odd elements <= M
        // For constraint sum(max(0,x[i]-M)) <= M:
        // Let y[i] = max(0, x[i]-M), sum(y[i]) <= M
        // This means the "excess above M" totals at most M
        // Since sum(x[i])=3M, if we let z[i]=min(x[i],M), sum(z[i])=3M-sum(y[i])>=2M
        // So constraint 2: sum(max(0,x[i]-M)) <= M
        // Now count sequences with sum=3M, odd_count<=M, sum(max(0,x[i]-M))<=M
        // Use inclusion-exclusion on odd_count and excess
        // Let's do DP[n][sum_x][odd_count][excess] - still large
        // For small N,M brute force
        // Let me think about the structure more
        // Actually for N>=2 and M>=1, let me try DP with states (remaining_sum, excess_used, odd_count)
        // and iterate over N positions
        // sum up to 3M (<=3M), excess up to M, odd_count up to M
        // So states: N * 3M * M * M which could be large
        // Let's just implement and hope M is small

        // Actually the problem doesn't specify constraints on N and M!
        // Let me re-read... it just says N integers and M operations.
        // I'll assume small constraints and do DP.

        // DP[i][s][e][o] = number of ways to fill positions 1..i
        // s = sum so far, e = total excess, o = odd count
        // Transition: for each value v >= 0 for position i+1
        // s+v <= 3M, e + max(0,v-M) <= M, o + (v%2) <= M

        long[][][][] dp = new long[N+1][3*M+1][M+1][M+1];
        dp[0][0][0][0] = 1;
        for(int i=0;i<N;i++){
            for(int s=0;s<=3*M;s++){
                for(int e=0;e<=M;e++){
                    for(int o=0;o<=M;o++){
                        if(dp[i][s][e][o]==0) continue;
                        long val = dp[i][s][e][o];
                        // try all values v for position i+1
                        for(int v=0;v<=3*M-s;v++){
                            int ns = s+v;
                            int ne = e + Math.max(0,v-M);
                            int no = o + (v%2);
                            if(ne>M||no>M) continue;
                            dp[i+1][ns][ne][no] = (dp[i+1][ns][ne][no]+val)%MOD;
                        }
                    }
                }
            }
        }
        long ans = 0;
        for(int e=0;e<=M;e++)
            for(int o=0;o<=M;o++)
                ans=(ans+dp[N][3*M][e][o])%MOD;
        System.out.println(ans);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 998244353L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        int M = fs.nextInt();

        // dp[a][b]:
        // after processing some number of positions,
        // a = total number of "2-assignments" used so far
        // b = total sum contributed so far = sum x[i] over processed positions
        //
        // For one position, if it received p times the +2 and q times the +1,
        // then value is 2p+q, with constraints:
        //   0 <= p <= M
        //   0 <= q <= M-p   (since in each operation i != j, total +2 uses = M, total +1 uses = M)
        // Across all positions:
        //   sum p_i = M
        //   sum q_i = M
        // Hence total sum values = 3M.
        //
        // For a fixed final sequence x, existence is equivalent to choosing p_i such that
        //   max(0, x_i - M) <= p_i <= floor(x_i/2)
        // and sum p_i = M.
        //
        // We count all sequences x by DP over positions, tracking possible total p and total x-sum.
        //
        // Transition for one position:
        // choose p and q => contributes a+=p, b+=2p+q, with q <= M-p
        // so value contribution v can be any integer in [2p, M+p].
        //
        // Thus for fixed p, contribution v ranges continuously.
        //
        // dp update:
        // ndp[a+p][b+v] += dp[a][b] for all v in [2p, M+p]
        //
        // Use prefix sums over b for O(N * M * M * 3M), which is fine for typical constraints
        // when N,M are moderate. This is the intended combinational DP.

        int maxA = M;
        int maxB = 3 * M;

        long[][] dp = new long[maxA + 1][maxB + 1];
        dp[0][0] = 1;

        for (int pos = 0; pos < N; pos++) {
            long[][] ndp = new long[maxA + 1][maxB + 1];

            // prefix sums over b for each a
            long[][] pref = new long[maxA + 1][maxB + 2];
            for (int a = 0; a <= maxA; a++) {
                long run = 0;
                for (int b = 0; b <= maxB; b++) {
                    run += dp[a][b];
                    if (run >= MOD) run -= MOD;
                    pref[a][b + 1] = run;
                }
            }

            for (int na = 0; na <= maxA; na++) {
                for (int nb = 0; nb <= maxB; nb++) {
                    long val = 0;
                    // previous a = pa, choose p = na - pa
                    // contribution v in [2p, M+p], so previous b must be in [nb-(M+p), nb-2p]
                    for (int pa = 0; pa <= na; pa++) {
                        int p = na - pa;
                        int l = nb - (M + p);
                        int r = nb - 2 * p;
                        if (r < 0 || l > maxB) continue;
                        if (l < 0) l = 0;
                        if (r > maxB) r = maxB;
                        if (l > r) continue;
                        long add = pref[pa][r + 1] - pref[pa][l];
                        if (add < 0) add += MOD;
                        val += add;
                        if (val >= MOD) val -= MOD;
                    }
                    ndp[na][nb] = val;
                }
            }
            dp = ndp;
        }

        System.out.println(dp[M][3 * M] % MOD);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
